import { WhopAPI } from "@whop-sdk/api";

export const whop = WhopAPI({ token: process.env.WHOP_API_KEY });

export async function verifyAccess(userToken: string, productId: string): Promise<boolean> {
  try {
    const membership = await whop.GET("/v5/memberships", {
      params: { query: { product_id: productId } },
      headers: { Authorization: `Bearer ${userToken}` },
    });
    return (membership.data?.data?.length ?? 0) > 0;
  } catch {
    return false;
  }
}
